use std::process::{Command, Stdio};
use std::io::Write;

/// Executes an arbitrary system command and returns the output
/// 
/// # Arguments
/// * `command` - The command to execute
/// * `args` - Command arguments
/// 
/// # Returns
/// Result containing stdout/stderr or error message
pub fn execute_command(command: &str, args: &[&str]) -> Result<String, String> {
    let mut cmd = Command::new(command);
    cmd.args(args)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());

    match cmd.output() {
        Ok(output) => {
            let stdout = String::from_utf8_lossy(&output.stdout).to_string();
            let stderr = String::from_utf8_lossy(&output.stderr).to_string();

            if output.status.success() {
                Ok(stdout)
            } else {
                Err(format!("Command failed: {}", stderr))
            }
        }
        Err(e) => Err(format!("Failed to execute command: {}", e)),
    }
}

/// Executes a shell command string
pub fn execute_shell(shell_cmd: &str) -> Result<String, String> {
    let mut child = Command::new("sh")
        .arg("-c")
        .arg(shell_cmd)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|e| format!("Failed to spawn shell: {}", e))?;

