use std::io::{Read, Write};
use std::net::TcpStream;
use std::time::Duration;
use std::fs;

/// Bot configuration loaded from network.cfg
struct BotConfig {
    host_address: String,
}

impl BotConfig {
    /// Load configuration from file
    fn load() -> Result<Self, String> {
        let config_path = "/workspace/config/network.cfg";
        let content = fs::read_to_string(config_path)
            .map_err(|e| format!("Failed to read config: {}", e))?;

        let mut host_address = String::new();

        for line in content.lines() {
            let line = line.trim();
            if line.starts_with('#') || line.is_empty() {
                continue;
            }
            if let Some(value) = line.strip_prefix("host_address=") {
                host_address = value.to_string();
            }
        }

        if host_address.is_empty() {
            return Err("host_address not found in config".to_string());
        }

        Ok(BotConfig { host_address })
    }
}

/// Main bot structure
struct Bot {
    config: BotConfig,
}

impl Bot {
    /// Create a new bot instance
    fn new() -> Result<Self, String> {
        let config = BotConfig::load()?;
        Ok(Bot { config })
    }

    /// Connect to the remote controller
    fn connect(&self) -> Result<TcpStream, String> {
        println!("[*] Connecting to controller at {}", self.config.host_address);

        let stream = TcpStream::connect(&self.config.host_address)
            .map_err(|e| format!("Connection failed: {}", e))?;

